mapper.select:
SELECT caps.*, apst.project_grade, apst.predict_rate, cpe.al_release_amount, CASE WHEN (nvl(round(caps.subscribe_amount/cap.issue_amount*100,2),0)<1 AND nvl( round(caps.subscribe_amount/cap.issue_amount*100,2),0)>0) THEN nvl( round(caps.subscribe_amount/cap.issue_amount*100,2),0) || '%' ELSE nvl( round(caps.subscribe_amount/cap.issue_amount*100,2),0) || '%' END sub_percent FROM ct_abs_product_subscribe caps JOIN ct_abs_product cap ON cap.product_id=caps.product_id LEFT JOIN ct_abs_product_structure apst ON apst.structure_id=caps.structure_id LEFT JOIN ( SELECT r.subscribe_id, SUM(r.release_amount) al_release_amount FROM ct_abs_product_release r WHERE r.release_status='CONFIRM' GROUP BY r.subscribe_id ) cpe ON cpe.subscribe_id=caps.subscribe_id WHERE 1=1
and caps.product_id = #{productId}
AND caps.rele_credit_flag='Y' AND caps.subscribe_status='CONFIRM' AND caps.subscribe_amount > nvl(cpe.al_release_amount,0)

SELECT
    nvl(SUM(caps.subscribe_amount),0)
 FROM
     ct_abs_product_subscribe caps

       caps.product_id = #{productId}
       and caps.STRUCTURE_ID =#{structureId,jdbcType=BIGINT}
